function Row({ title }) {
  return (
    <div className="row">
      <h2>{title}</h2>
      <div className="row-posters">
        <img loading="lazy" src="https://via.placeholder.com/150" />
        <img loading="lazy" src="https://via.placeholder.com/150" />
        <img loading="lazy" src="https://via.placeholder.com/150" />
      </div>
    </div>
  );
}

export default Row;
